    correction: [{"quoi":"القاعدة","math":"التواتر هو التكرار مقسوما على التكرار الجملي ; و النسبة المائوية هي التواتر في 100 ; و قيس الزاوية هو التواتر في 360"},{"quoi":"التكرار الجملي","math":"<span dir=\"ltr\" class=\"expr\">N = 40</span>"},{"quoi":"التواتر الأوّل","math":"<span dir=\"ltr\" class=\"expr\">fa = <span class=\"frac\"><span class=\"num\">12</span><span class=\"den\">40</span></span></span>"},{"quoi":"أي بالنسبة المائوية","math":"<span dir=\"ltr\" class=\"expr\">pa = 30</span>"},{"quoi":"نتحقّق أنّ مجموع النسب يساوي 100","math":"<span dir=\"ltr\" class=\"expr\">30 + 30 + 40 = 100</span>"},{"quoi":"الزاوية المطلوبة","math":"<span dir=\"ltr\" class=\"expr\">ga = 360 × <span class=\"frac\"><span class=\"num\">12</span><span class=\"den\">40</span></span></span>"},{"quoi":"أي","math":"<span dir=\"ltr\" class=\"expr\">ga = 108</span>"},{"quoi":"النتيجة","math":"قيس الزاوية الموافقة هو 108 درجة"}],
