    correction: [{"quoi":"القاعدة","math":"مضلّع التكرارات المتراكمة الصاعدة يصل النقط (طرف الفئة الأعلى ؛ التراكم)، انطلاقا من (الطرف الأوّل ؛ 0) ; و الموسّط هو فاصلة النقطة التي ترتيبها تساوي نصف التكرار الجملي — أي 50٪ إذا كان المحور بالنسب المائوية، و 0,5 إذا كان بالتواترات"},{"quoi":"نحسب التكرار الجملي","math":"<span dir=\"ltr\" class=\"expr\">N = 188</span>"},{"quoi":"نكوّن التراكم الصاعد","math":"<span dir=\"ltr\" class=\"expr\">ca = 67</span>"},{"quoi":"و نواصل إلى الأخير","math":"<span dir=\"ltr\" class=\"expr\">ce = N</span>"},{"quoi":"نضع النقط في معلم ثمّ نصلها","math":"النقط هي (طرف كلّ فئة الأعلى ؛ تراكمها)، و أوّلها (5 ؛ 0)"},{"quoi":"نحسب نصف التكرار الجملي","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">N</span><span class=\"den\">2</span></span> = 94</span>"},{"quoi":"نرسم المستقيم الأفقي ذا الترتيب <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">N</span><span class=\"den\">2</span></span></span>","math":"يقطع المضلّع في نقطة واحدة"},{"quoi":"نقرأ فاصلة نقطة التقاطع","math":"القراءة تقع داخل الفئة [15 ; 20[، بين التراكمين 81 و 146"},{"quoi":"النتيجة","math":"الموسّط هو <span dir=\"ltr\" class=\"expr\">Me = 16</span>، و هو فاصلة النقطة التي ترتيبها 94 على المضلّع الصاعد"}],
